return items.map((item) => {
  const fixture = item.json;
  const state = fixture.kind === 'happy' ? 'READY_FOR_REVIEW' : fixture.kind === 'edge' ? 'REVIEW_REQUIRED' : 'STOPPED_FOR_REVIEW';
  return { json: {
    workflow: fixture.workflow,
    scenario: fixture.id,
    evidenceType: 'Synthetic Demo',
    status: state,
    humanRequired: true,
    correlationId: fixture.input.eventId,
    idempotencyKey: fixture.input.eventId,
    exceptions: fixture.kind === 'happy' ? [] : [{ code: fixture.kind === 'edge' ? 'REVIEW_RULE' : 'STOP_RULE', message: fixture.label }],
    audit: ['INPUT_RECEIVED', 'NORMALIZED', 'RULES_CHECKED', state],
    sourceInput: fixture.input
  } };
});

return items.map((item) => ({ json: {
  ...item.json,
  implementationStatus: 'Built and testable',
  adapterStatus: 'Mocked adapter',
  humanDecision: 'pending',
  targetSystem: 'DMS/QMS bleibt führend',
  preparedOutput: { target: 'DOC_DRAFT', sourceEvent: item.json.correlationId },
  externalWritePerformed: false,
  terminalMessage: 'Prepared for human review; no external write.'
} }));
